40	    pub fn scan_dotfiles(&self, dotfile_names: &[String]) -> Vec<Dotfile> {
41	        let mut found = Vec::new();
42	
43	        for name in dotfile_names {
44	            let path = self.home_dir.join(name);
45	            // Only include if the path actually exists (file or directory)
